// Reads results/metrics.json (generated by src/evaluate.py). No metric is hardcoded in the UI.
import raw from "../../../results/metrics.json";

export interface ClassMetrics { precision: number; recall: number; f1: number; support: number }
export interface Metrics {
  generated_at_utc: string;
  model: string;
  weights_sha256: string;
  test_samples: number;
  class_order: string[];
  accuracy: number;
  macro_f1: number;
  per_class: Record<string, ClassMetrics>;
  confusion_matrix: number[][];
}
export const metrics = raw as unknown as Metrics;

